-- Super Gatorlator 64: the campus crowd. 40 students (actors/npc_01 .. npc_40, random Gatorize characters built by
-- tools/npcs/make_campus_npcs.py) walk the hub's sidewalks (sgl_campus_npc_routes.lua, generated by
-- tools/npcs/campus_routes.py from the OSM footways and the built hub's collision). They are scenery: no talking,
-- no missions, and they gently push players out of their way.
--
-- Two kinds, all local props (spawn_non_sync_object) on every client in the hub:
--   synced (npc_01..24)   hang out near landmarks (SGL_CROWD_ANCHORS). Where they walk comes from a seeded random walk
--                         on the sidewalk graph that restarts from fixed nodes at the start of every SGL_CROWD_EPOCH
--                         (get_time()), so every client computes the same crowd without sending a packet: a player
--                         arriving in the hub fast-forwards each one from the epoch's start to now.
--   ambient (npc_25..40)  keep around YOU, wherever you go (SGL_CROWD_AROUND): they drift toward you at junctions,
--                         and one that ends up too far away, off camera, reappears on a sidewalk near you, out of view.
--                         Each client has its own (they never need to agree), so campus is busy wherever anyone is.
--
-- The models are Mario-rigged, so the students play Mario's own animations (get_mario_vanilla_animation): walking,
-- and looking around while they stop for a moment. /crowd off hides them, /crowd on brings them back.

SGL_CROWD_EPOCH = 1200        -- seconds; every client restarts the synced walk from the same nodes each epoch
SGL_CROWD_ANIM_Y = 189        -- Mario's animYTrans: scales his animations' root height to his model
SGL_CROWD_PUSH_RADIUS = 55    -- players are pushed out of this cylinder around a student
SGL_CROWD_DRAW_DIST = 7000

-- where the synced students hang out: count per anchor, each keeps within `leash` units of it (game units, x / z)
SGL_CROWD_ANCHORS = {
    { name = "Plaza of the Americas", x = 8320, z = -4440, leash = 5000, count = 8 },
    { name = "Century Tower", x = 4400, z = 9500, leash = 4000, count = 3 },
    { name = "University Auditorium", x = 8350, z = 3515, leash = 3500, count = 2 },
    { name = "Library West", x = 8391, z = -16043, leash = 4000, count = 3 },
    { name = "Turlington Plaza", x = -1200, z = 7330, leash = 4000, count = 3 },
    { name = "Marston", x = -1350, z = 16700, leash = 4000, count = 3 },
    { name = "Smathers Library", x = 17195, z = -14681, leash = 4000, count = 2 },
}

-- the ambient students around the local player (units): they start between `near` and `far` from you, turn toward
-- you at junctions beyond `leash`, and past `recycle` (off camera) reappear `respawn` units away, out of view
SGL_CROWD_AROUND = { first = 25, count = 16, near = 600, far = 4500, leash = 3000, recycle = 5200,
                     respawn = { 2400, 4500 } }

local IDLE_ANIMS = { MARIO_ANIM_IDLE_HEAD_LEFT, MARIO_ANIM_IDLE_HEAD_RIGHT, MARIO_ANIM_IDLE_HEAD_CENTER }

---------------------------------------------------------------------------------------------
-- the sidewalk graph
---------------------------------------------------------------------------------------------
local sNodes = SGL_CAMPUS_ROUTES.nodes
local sAdj = {}
for i = 1, #sNodes do sAdj[i] = {} end
for _, l in ipairs(SGL_CAMPUS_ROUTES.links) do
    table.insert(sAdj[l[1]], l[2])
    table.insert(sAdj[l[2]], l[1])
end

local function dist2d(ax, az, bx, bz)
    local dx, dz = ax - bx, az - bz
    return math.sqrt(dx * dx + dz * dz)
end

-- nodes within each anchor's leash (where its students start an epoch)
for _, a in ipairs(SGL_CROWD_ANCHORS) do
    a.nodes = {}
    for i, n in ipairs(sNodes) do
        if #sAdj[i] > 0 and dist2d(n[1], n[3], a.x, a.z) <= a.leash then table.insert(a.nodes, i) end
    end
end

-- the ambient students' moving anchor: the local player (updated every frame they run)
local sAround = { name = "you", x = 0, z = 0, leash = SGL_CROWD_AROUND.leash }

---------------------------------------------------------------------------------------------
-- the students
---------------------------------------------------------------------------------------------
SGL_CROWD = {}
SGL_CROWD_SYNCED = 0
do
    local function add(i, anchor, ambient)
        local id = string.format("npc_%02d", i)
        local model = smlua_model_util_get_id(id .. "_geo")
        if model ~= E_MODEL_ERROR_MODEL and (ambient or #anchor.nodes > 0) then
            table.insert(SGL_CROWD, { index = i, id = id, model = model, anchor = anchor, ambient = ambient })
        end
    end
    local i = 0
    for _, a in ipairs(SGL_CROWD_ANCHORS) do
        for _ = 1, a.count do
            i = i + 1
            add(i, a, false)
        end
    end
    SGL_CROWD_SYNCED = #SGL_CROWD
    local A = SGL_CROWD_AROUND
    for k = A.first, A.first + A.count - 1 do add(k, sAround, true) end
end

-- deterministic random numbers (the same on every client): an LCG per student
local function rnd(s)
    s.seed = (s.seed * 1103515245 + 12345) % 2147483648
    return s.seed / 2147483648
end

local function pick(s, list) return list[math.floor(rnd(s) * #list) + 1] end

local function set_link(s, a, b)
    s.a, s.b, s.pos = a, b, 0
    local na, nb = sNodes[a], sNodes[b]
    s.len = math.max(1, dist2d(na[1], na[3], nb[1], nb[3]))
end

-- reached node s.b: maybe stop a moment, then choose the next link (no U-turn unless it's a dead end)
local function arrive(s)
    local from, at = s.a, s.b
    local options = {}
    for _, n in ipairs(sAdj[at]) do
        if n ~= from then table.insert(options, n) end
    end
    if #options == 0 then options = { from } end
    local nxt
    local an = s.anchor
    local here = sNodes[at]
    if #options > 1 and dist2d(here[1], here[3], an.x, an.z) > an.leash and rnd(s) < 0.85 then
        local bestD = math.huge
        for _, n in ipairs(options) do
            local d = dist2d(sNodes[n][1], sNodes[n][3], an.x, an.z)
            if d < bestD then nxt, bestD = n, d end
        end
    else
        nxt = pick(s, options)
    end
    set_link(s, at, nxt)
    if rnd(s) < 0.12 then
        s.pause = 60 + math.floor(rnd(s) * 150)
        s.idle = pick(s, IDLE_ANIMS)
    end
end

-- walk `frames` frames along the graph (whole links at a time, so catching up a whole epoch is cheap)
local function advance(s, frames)
    while frames > 0 do
        if s.pause > 0 then
            local take = math.min(s.pause, frames)
            s.pause, frames = s.pause - take, frames - take
        else
            local need = (s.len - s.pos) / s.speed
            if need > frames then
                s.pos, frames = s.pos + s.speed * frames, 0
            else
                frames = frames - need
                arrive(s)
            end
        end
    end
end

-- a fresh walk from node a: speed, side of the path, first link, a point along it
local function start_walk(s, a)
    s.speed = 3.2 + rnd(s) * 1.2                 -- units per frame (about 1-1.3 m/s)
    s.side = (rnd(s) < 0.5 and -1 or 1) * (10 + rnd(s) * 25)
    s.pause, s.idle = 0, IDLE_ANIMS[1]
    set_link(s, a, pick(s, sAdj[a]))
    s.pos = rnd(s) * s.len
end

-- the start of an epoch (synced students): the same node, link, speed and side of the path on every client
local function start_epoch(s, epoch)
    s.seed = (epoch * 7919 + s.index * 104729) % 2147483648
    for _ = 1, 4 do rnd(s) end
    start_walk(s, pick(s, s.anchor.nodes))
end

-- position on the current link (+ its side offset) and the walking direction
local function place_of(s)
    local na, nb = sNodes[s.a], sNodes[s.b]
    local t = s.pos / s.len
    local dx, dz = nb[1] - na[1], nb[3] - na[3]
    local ox, oz = dz / s.len * s.side, -dx / s.len * s.side
    return na[1] + dx * t + ox, na[2] + (nb[2] - na[2]) * t, na[3] + dz * t + oz, atan2s(dz, dx)
end

-- roughly in front of the camera (within ~70 degrees of where it looks); false when the camera is unknown
local function camera_sees(x, z)
    local l = gLakituState
    if l == nil or l.curPos == nil or l.curFocus == nil then return false end
    local cx, cz = l.curPos.x, l.curPos.z
    local fx, fz = l.curFocus.x - cx, l.curFocus.z - cz
    local px, pz = x - cx, z - cz
    local fl, pl = math.sqrt(fx * fx + fz * fz), math.sqrt(px * px + pz * pz)
    if fl < 1 then return false end
    if pl < 1 then return true end
    return (fx * px + fz * pz) / (fl * pl) > 0.35
end

-- an ambient student starts walking on a sidewalk node minD..maxD from the player (out of view when `hidden` and
-- there is one); false when no sidewalk is that close (the player is far from every path)
local function place_ambient(s, minD, maxD, hidden)
    local seen, unseen = {}, {}
    for i, n in ipairs(sNodes) do
        if #sAdj[i] > 0 then
            local d = dist2d(n[1], n[3], sAround.x, sAround.z)
            if d >= minD and d <= maxD then
                table.insert((hidden and camera_sees(n[1], n[3])) and seen or unseen, i)
            end
        end
    end
    local list = #unseen > 0 and unseen or seen
    if #list == 0 then return false end
    s.seed = math.random(1, 2147483646)
    start_walk(s, list[math.random(#list)])
    return true
end

local function update_around()
    local m = gMarioStates[0]
    sAround.x, sAround.z = m.pos.x, m.pos.z
end

---------------------------------------------------------------------------------------------
-- objects (oBehParams = index into SGL_CROWD)
---------------------------------------------------------------------------------------------
-- play one of Mario's animations on a student (set_mario_anim_with_accel for an object); accel 0x10000 = 1x
local function play(o, s, animId, accel)
    local info = o.header.gfx.animInfo
    if s.playing ~= animId then
        local anim = get_mario_vanilla_animation(animId)
        if anim == nil then return end
        s.playing = animId
        info.animID = animId
        info.curAnim = anim
        info.animYTrans = SGL_CROWD_ANIM_Y
        info.animFrameAccelAssist = (anim.startFrame << 16) + accel
        info.animFrame = anim.startFrame
    end
    info.animAccel = accel
end

local function crowd_init(o)
    o.oFlags = OBJ_FLAG_UPDATE_GFX_POS_AND_ANGLE | OBJ_FLAG_ACTIVE_FROM_AFAR
    o.oDrawingDistance = SGL_CROWD_DRAW_DIST
    o.oIntangibleTimer = -1
end

local function nearest_player(o, range)
    local me = gNetworkPlayers[0]
    local best, bestD = nil, range
    for i = 0, MAX_PLAYERS - 1 do
        local np, m = gNetworkPlayers[i], gMarioStates[i]
        if np.connected and np.currLevelNum == me.currLevelNum and np.currAreaIndex == me.currAreaIndex then
            local d = dist2d(m.pos.x, m.pos.z, o.oPosX, o.oPosZ)
            if d < bestD then best, bestD = m, d end
        end
    end
    return best
end

local function crowd_loop(o)
    local s = SGL_CROWD[o.oBehParams]
    if s == nil or s.obj ~= o then
        obj_mark_for_deletion(o)
        return
    end
    if s.ambient then
        update_around()
        -- twice a second: too far from me and off camera -> start again near me, out of view
        if (o.oTimer + s.index) % 15 == 0 and dist2d(o.oPosX, o.oPosZ, sAround.x, sAround.z) > SGL_CROWD_AROUND.recycle
                and not camera_sees(o.oPosX, o.oPosZ) then
            local r = SGL_CROWD_AROUND.respawn
            if place_ambient(s, r[1], r[2], true) then
                local x, y, z, yaw = place_of(s)
                o.oPosX, o.oPosY, o.oPosZ, o.oFaceAngleYaw = x, y, z, yaw
            end
        end
    end
    advance(s, 1)
    local x, y, z, yaw = place_of(s)
    o.oPosX, o.oPosY, o.oPosZ = x, y, z
    if s.pause > 0 then
        -- stopped: look at a player close by, else keep facing the way
        local m = nearest_player(o, 450)
        if m ~= nil then yaw = atan2s(m.pos.z - o.oPosZ, m.pos.x - o.oPosX) end
        play(o, s, s.idle, 0x10000)
    else
        play(o, s, MARIO_ANIM_WALKING, math.floor(s.speed / 4 * 0x10000))
    end
    o.oFaceAngleYaw = approach_s16_symmetric(o.oFaceAngleYaw, yaw, 0x800)
    o.oMoveAngleYaw = o.oFaceAngleYaw
    cur_obj_push_mario_away_from_cylinder(SGL_CROWD_PUSH_RADIUS, 160)
end

id_bhvSglCrowd = hook_behavior(nil, OBJ_LIST_DEFAULT, true, crowd_init, crowd_loop, "bhvSglCrowd")

local sEnabled = true

local function despawn_all()
    for _, s in ipairs(SGL_CROWD) do
        if s.obj ~= nil then obj_mark_for_deletion(s.obj) end
        s.obj, s.playing = nil, nil
    end
end

local function spawn_all()
    local np = gNetworkPlayers[0]
    if not sEnabled or np.currLevelNum ~= SGL_HUB_LEVEL or np.currAreaIndex ~= 1 then return end
    if sgl_bridge_is_host ~= nil and sgl_bridge_is_host() then return end   -- nobody watches the headless host
    local now = get_time()
    local epoch = now // SGL_CROWD_EPOCH
    update_around()
    local A = SGL_CROWD_AROUND
    for k, s in ipairs(SGL_CROWD) do
        local ok = true
        if s.ambient then
            ok = place_ambient(s, A.near, A.far, false)
        else
            start_epoch(s, epoch)
            advance(s, (now - epoch * SGL_CROWD_EPOCH) * 30)
        end
        if ok then
            local x, y, z, yaw = place_of(s)
            s.obj = spawn_non_sync_object(id_bhvSglCrowd, s.model, x, y, z, function(obj)
                obj.oBehParams = k
                obj.oFaceAngleYaw = yaw
                obj.oMoveAngleYaw = yaw
            end)
        end
    end
end

local function on_level_init()
    for _, s in ipairs(SGL_CROWD) do s.obj = nil end   -- the level change removed the old objects
    despawn_all()
    spawn_all()
end

-- where student k is right now (tests and debugging): x, y, z
function sgl_crowd_pos(k)
    local s = SGL_CROWD[k]
    if s == nil or s.a == nil then return nil end
    local x, y, z = place_of(s)
    return x, y, z
end

hook_chat_command("crowd", "[on|off] - show or hide the students walking around campus", function(msg)
    local arg = (msg or ""):lower():match("^%s*(%S*)")
    if arg == "off" then
        sEnabled = false
        despawn_all()
    elseif arg == "on" then
        if not sEnabled then
            sEnabled = true
            despawn_all()
            spawn_all()
        end
    elseif arg ~= "" then
        return false
    end
    djui_chat_message_create(string.format("Campus crowd: %s (%d students)", sEnabled and "on" or "off", #SGL_CROWD))
    return true
end)

hook_event(HOOK_ON_LEVEL_INIT, on_level_init)
